        this.status = OrderStatus.PLACED;
        this.amountPaid = BigDecimal.ZERO;
        this.amountRefunded = BigDecimal.ZERO;
    }

    private Order(Order other) {
        this.id = other.id;
        this.customerId = other.customerId;
        this.total = other.total;
        this.status = other.status;
        this.amountPaid = other.amountPaid;
        this.amountRefunded = other.amountRefunded;
    }

    /** A snapshot, so that a repository can hand out orders without sharing state with its stored copy. */
    public Order copy() {
        return new Order(this);
    }

    public String id() {
        return id;
    }

    public String customerId() {
        return customerId;
    }

    public BigDecimal total() {
        return total;
    }

    public OrderStatus status() {
        return status;
    }

    public BigDecimal amountPaid() {
        return amountPaid;
    }

    public BigDecimal amountRefunded() {
        return amountRefunded;
    }

    public void markPaid(BigDecimal amount) {
        this.status = OrderStatus.PAID;
        this.amountPaid = amount;
    }

    public void markShipped() {
        this.status = OrderStatus.SHIPPED;
    }

    public void markDelivered() {
        this.status = OrderStatus.DELIVERED;
    }

    public void cancel() {
        this.status = OrderStatus.CANCELLED;
    }
}

package shop;

/** Wires every command to its handler. */
public final class OrderServices {

    private OrderServices() {}

    public static CommandBus createBus(OrderRepository orders) {
        CommandBus bus = new CommandBus();
        bus.register(PlaceOrder.class, new PlaceOrderHandler(orders));
        bus.register(PayOrder.class, new PayOrderHandler(orders));
        bus.register(ShipOrder.class, new ShipOrderHandler(orders));
        bus.register(DeliverOrder.class, new DeliverOrderHandler(orders));
        bus.register(CancelOrder.class, new CancelOrderHandler(orders));
        return bus;
    }
}
